-- Independent Basic and Fashion photo banks; existing seven images become Basic.
CREATE TABLE model_telegram_photo_sets (model_id TEXT NOT NULL REFERENCES models(id) ON DELETE CASCADE,style TEXT NOT NULL CHECK(style IN ('basic','fashion')),position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 7),telegram_file_id TEXT NOT NULL,telegram_file_unique_id TEXT NOT NULL,uploaded_by TEXT NOT NULL,source_chat_id TEXT NOT NULL,source_thread_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(model_id,style,position));
INSERT INTO model_telegram_photo_sets(model_id,style,position,telegram_file_id,telegram_file_unique_id,uploaded_by,source_chat_id,source_thread_id,created_at,updated_at) SELECT model_id,'basic',position,telegram_file_id,telegram_file_unique_id,uploaded_by,source_chat_id,source_thread_id,created_at,updated_at FROM model_telegram_photos;
ALTER TABLE secretary_photo_replacement_pending ADD COLUMN style TEXT NOT NULL DEFAULT 'basic' CHECK(style IN ('basic','fashion'));
ALTER TABLE secretary_composite_batch_items ADD COLUMN style TEXT NOT NULL DEFAULT 'basic' CHECK(style IN ('basic','fashion'));
ALTER TABLE secretary_composite_batch_items ADD COLUMN language TEXT NOT NULL DEFAULT 'ru' CHECK(language IN ('ru','en'));
ALTER TABLE composite_topic_publications ADD COLUMN style TEXT NOT NULL DEFAULT 'basic' CHECK(style IN ('basic','fashion'));
ALTER TABLE composite_topic_publications ADD COLUMN language TEXT NOT NULL DEFAULT 'ru' CHECK(language IN ('ru','en'));
CREATE TABLE secretary_composite_request_pending(chat_id TEXT NOT NULL,thread_id INTEGER NOT NULL,user_id TEXT NOT NULL,stage TEXT NOT NULL CHECK(stage IN ('style','language','names')),style TEXT CHECK(style IN ('basic','fashion')),language TEXT CHECK(language IN ('ru','en')),names_text TEXT,command_message_id INTEGER,prompt_message_id INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(chat_id,thread_id,user_id));
